impl Backoff {
    /// Create a new backoff starting at `initial_ms`, capped at `max_ms`.
    pub fn new(initial_ms: u64, max_ms: u64) -> Self {
        Self {
            current_ms: initial_ms,
            max_ms,
            multiplier: 2,
        }
