                        }
                    }
                }
                #[cfg(not(target_os = "windows"))]
                {
                    use std::alloc::{dealloc, Layout};
                    if let Ok(layout) = Layout::from_size_align(self.mapped_size, HUGE_PAGE_SIZE) {
                        unsafe { dealloc(self.ptr, layout) };
                    }
                }
            }
            self.ptr = ptr::null_mut();
        }
    }
