    match xp {
        x if x >= XP_GROK => "Grok",
        x if x >= XP_COSMIC => "Cosmic",
        x if x >= XP_OMNISCIENT => "Omniscient",
        x if x >= XP_TRANSCENDENT => "Transcendent",
        x if x >= XP_SENTIENT => "Sentient",
        x if x >= XP_AWARE => "Aware",
        _ => "Dormant",
    }
