    pub fn from_env() -> WarpResult<Self> {
        let s = std::env::var("WARP_STELLAR_RELAY_KEY").map_err(|_| WarpError::AdapterError {
            chain: "stellar".into(),
            reason: "WARP_STELLAR_RELAY_KEY env var not set".into(),
