    pub fn from_str_key(secret: &str, network: String) -> WarpResult<Self> {
        let priv_key = StellarPrivKey::from_string(secret).map_err(|e| WarpError::AdapterError {
            chain: "stellar".into(),
            reason: format!("Stellar StrKey parse error: {:?}", e),
        })?;
